changeSet.sql:
CREATE TABLE stories ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, media_url TEXT NOT NULL, media_type TEXT NOT NULL CHECK (media_type IN ('image','video')), duration_seconds DOUBLE PRECISION, views_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), expires_at TIMESTAMPTZ NOT NULL, deleted_at TIMESTAMPTZ,
CONSTRAINT STORIES_EXPIRES_CHK CHECK (expires_at > created_at), CONSTRAINT STORIES_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE );
CREATE INDEX idx_stories_profile ON stories(profile_id, created_at DESC) WHERE deleted_at IS NULL; CREATE INDEX idx_stories_active ON stories(profile_id, expires_at DESC) WHERE deleted_at IS NULL;
